  text2 = text2.replace(/https?:\/\/(?!github\.com|docs\.github\.com)[^\s)\]]+/g, "[REDACTED:EXTERNAL_URL]");
  text2 = text2.replace(/(?:curl|wget|nc|ncat|bash|sh|python3?|node|ruby|perl)\s+[^\n]+/g, "[REDACTED:SHELL_CMD]");
