var BORDERLINE_MIN = 60;
var BORDERLINE_MAX = 80;
var VerificationSchema = external_exports.object({
  confirmed: external_exports.enum(["yes", "no"]).describe("Is this issue real and actionable?")
});
async function calibrateConfidence(review, config2) {
  const borderline = review.comments.filter(
    (c) => c.confidence >= BORDERLINE_MIN && c.confidence <= BORDERLINE_MAX
  );
  const nonBorderline = review.comments.filter(
    (c) => c.confidence < BORDERLINE_MIN || c.confidence > BORDERLINE_MAX
  );
  const result = nonBorderline.map((c) => ({
    ...c,
    calibratedConfidence: c.confidence > 80 ? "high" : c.confidence > 50 ? "medium" : "low"
  }));
  if (borderline.length === 0) return result;
  const secondModel = getSecondModel(config2);
  if (!secondModel) {
    return [
      ...result,
      ...borderline.map((c) => ({
        ...c,
        calibratedConfidence: "medium"
      }))
    ];
  }
  const concurrency = config2.pipelineParallel ? 3 : 1;
  const calibrated = await mapConcurrent(
    borderline,
    async (finding) => {
      try {
        const { object: object3 } = await generateObject({
          model: secondModel,
          prompt: `You are verifying a code review finding. Is this a real issue?

File: ${finding.file}, Line: ${finding.line}
Severity: ${finding.severity}, Category: ${finding.category}
Message: ${finding.message}
${finding.suggestion ? `Suggested fix: ${finding.suggestion}` : ""}

Is this issue real and actionable?`,
          schema: VerificationSchema,
          maxOutputTokens: 32
        });
        const isConfirmed = object3.confirmed === "yes";
        return {
          ...finding,
          calibratedConfidence: isConfirmed ? "high" : "low",
          confidence: isConfirmed ? Math.min(finding.confidence + 15, 100) : Math.max(finding.confidence - 20, 0)
        };
      } catch (e) {
        core6.warning(`Calibration failed for ${finding.file}:${finding.line}: ${e instanceof Error ? e.message : String(e)}`);
        return { ...finding, calibratedConfidence: "medium" };
      }
    },
    concurrency
  );
  result.push(...calibrated);
  const highCount = result.filter((c) => c.calibratedConfidence === "high").length;
  const lowCount = result.filter((c) => c.calibratedConfidence === "low").length;
  core6.info(`Confidence calibration: ${highCount} high, ${result.length - highCount - lowCount} medium, ${lowCount} low`);
  return result;
}
